void Solver::rephase() {
    rephases = 0;
    threshold *= 0.95; // Slow decay to avoid aggressive rephasing
    rephase_limit += 4096; // Smaller increment to rephase more frequently
    // With 70% probability: use local best phase
    // With 15% probability: use inverted local best phase
    // With 10% probability: use random phase
    // With 5% probability: keep current saved phases
    int phase_rand = rand() % 100;
    if ((phase_rand -= 70) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if ((phase_rand -= 15) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if ((phase_rand -= 10) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    }
    // else keep saved phases unchanged
}
